<?php
declare(strict_types=1); require_once __DIR__.'/../config/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='OPTIONS'){http_response_code(204);exit;} header('Cache-Control:no-store');
function input_json(): array { $raw=file_get_contents('php://input'); if($raw==='') return $_POST; $d=json_decode($raw,true); if(!is_array($d)) json_response(['success'=>false,'error'=>'Invalid JSON'],400); return $d; }
function api_key_ok(mysqli $db): void { $key=trim((string)($_SERVER['HTTP_X_DEVICE_KEY']??'')); if($key==='') return; /* optional device key mode */ }
$db=new Database();$c=$db->getConnection();$resource=trim((string)($_GET['resource']??''));$method=$_SERVER['REQUEST_METHOD'];
try{
 if($resource==='rfid-punch' && $method==='POST'){ $d=input_json(); $m=new RfidAttendance($c); $r=$m->punch((string)($d['card_uid']??''),(string)($d['device_code']??''),isset($d['event_id'])?(string)$d['event_id']:null,isset($d['punched_at'])?(string)$d['punched_at']:null); json_response($r,$r['success']?200:422); }
 if($resource==='rfid-cards' && $method==='GET'){json_response((new RfidAttendance($c))->cards());}
 if($resource==='rfid-card-register' && $method==='POST'){ $d=input_json(); (new RfidAttendance($c))->registerCard((int)($d['employee_id']??0),(string)($d['uid']??''),(string)($d['card_type']??'MIFARE')); json_response(['success'=>true,'message'=>'RFID card assigned'],201); }
 if($resource==='live' && $method==='GET'){json_response(['stats'=>(new RfidAttendance($c))->todayStats(),'punches'=>(new RfidAttendance($c))->live((int)($_GET['limit']??30))]);}
 if($resource==='heartbeat' && $method==='POST'){ $d=input_json();$code=trim((string)($d['device_code']??''));if($code==='')json_response(['success'=>false,'error'=>'device_code required'],422);$name=trim((string)($d['device_name']??$code));$loc=trim((string)($d['location']??''));$s=$c->prepare('INSERT INTO attendance_devices(device_code,device_name,location,status,last_seen_at) VALUES(?,?,?,"active",NOW()) ON DUPLICATE KEY UPDATE device_name=VALUES(device_name),location=VALUES(location),status="active",last_seen_at=NOW()');$s->bind_param('sss',$code,$name,$loc);$s->execute();json_response(['success'=>true,'message'=>'Heartbeat accepted']); }
 if($resource==='employees'){ $m=new Employee($c); if($method==='GET'){ $id=(int)($_GET['id']??0); json_response($id?($m->find($id)??[]):$m->all((string)($_GET['q']??''),max(1,(int)($_GET['page']??1)),min(100,max(1,(int)($_GET['limit']??20))))); } $d=input_json();$id=(int)($_GET['id']??0);if($method==='POST')json_response(['success'=>true,'id'=>$m->create($d)],201);if($method==='PUT'){if(!$id||!$m->find($id))json_response(['success'=>false,'error'=>'Employee not found'],404);$m->update($id,$d);json_response(['success'=>true]);}if($method==='DELETE'){if(!$id||!$m->find($id))json_response(['success'=>false,'error'=>'Employee not found'],404);$m->delete($id);json_response(['success'=>true]);}}
 json_response(['success'=>false,'error'=>'Unknown resource or method'],404);
}catch(InvalidArgumentException|RuntimeException $e){json_response(['success'=>false,'error'=>$e->getMessage()],422);}catch(mysqli_sql_exception $e){error_log($e->getMessage());json_response(['success'=>false,'error'=>'Database request failed'],409);}catch(Throwable $e){error_log($e->getMessage());json_response(['success'=>false,'error'=>'Internal server error'],500);}
